%% @doc The `EchoRequest.message' of every request a bench worker sends; see
%% `--payload' in bench/README.md. `repeat' is the letter x repeated;
%% `records' is new log records in every message, generated byte for byte as
%% bench/payload.py does.
-module(trevrpc_interop_payload).

-export([new/3, next/1, next/2]).

-export_type([payload/0]).

-record(records, {
    %% The xorshift64 state.
    state :: non_neg_integer(),
    %% The records generated so far.
    count = 0 :: non_neg_integer(),
    size :: non_neg_integer()
}).

-opaque payload() :: {repeat, binary()} | #records{}.

-define(MASK, 16#FFFFFFFFFFFFFFFF).
%% The generator seed of worker 0; worker i uses it plus i.
-define(WORKER_SEED, 16#9E3779B97F4A7C15).
%% The ts of the first record, before its jitter.
-define(BASE_TIMESTAMP_MS, 1790000000000).

%% @doc The payload of worker number `Worker', from 0, whose messages are
%% `Size' bytes.
-spec new(repeat | records, non_neg_integer(), non_neg_integer()) -> payload().
new(repeat, Size, _Worker) ->
    {repeat, binary:copy(<<"x">>, Size)};
new(records, Size, Worker) ->
    #records{state = (?WORKER_SEED + Worker) band ?MASK, size = Size}.

%% @doc The message of the next request.
-spec next(payload()) -> {binary(), payload()}.
next({repeat, Message} = Payload) ->
    {Message, Payload};
next(#records{size = Size} = Payload) ->
    next(Payload, Size).

%% @doc The next message of a `records' payload, `Size' bytes long whatever
%% the payload's size, as bench/payload.py's golden digest reads it.
-spec next(payload(), non_neg_integer()) -> {binary(), payload()}.
next(#records{} = Payload, Size) ->
    records(Payload, Size, [], 0).

%% Appends records until they reach `Size' bytes, then cuts them to it; the
%% rest of the last record is discarded.
records(Payload, Size, Acc, Length) when Length >= Size ->
    <<Message:Size/binary, _/binary>> = iolist_to_binary(lists:reverse(Acc)),
    {Message, Payload};
records(Payload, Size, Acc, Length) ->
    {Record, Next} = record(Payload),
    records(Next, Size, [Record | Acc], Length + byte_size(Record)).

record(#records{count = Count} = P0) ->
    {Jitter, P1} = between(0, 12, P0),
    Timestamp = ?BASE_TIMESTAMP_MS + Count * 13 + Jitter,
    {Service, P2} = pick(services(), P1#records{count = Count + 1}),
    {Region, P3} = pick(regions(), P2),
    {Method, P4} = pick(methods(), P3),
    {Route, P5} = pick(routes(), P4),
    {Status, P6} = pick(statuses(), P5),
    {Latency, P7} = between(1, 2000, P6),
    {Trace, P8} = trace(32, P7, []),
    {User, P9} = between(1, 1000000, P8),
    Record = iolist_to_binary([
        <<"{\"ts\":">>,
        integer_to_binary(Timestamp),
        <<",\"service\":\"">>,
        Service,
        <<"\",\"region\":\"">>,
        Region,
        <<"\",\"method\":\"">>,
        Method,
        <<"\",\"route\":\"">>,
        Route,
        <<"\",\"status\":">>,
        integer_to_binary(Status),
        <<",\"latency_ms\":">>,
        integer_to_binary(Latency),
        <<",\"trace\":\"">>,
        Trace,
        <<"\",\"user\":">>,
        integer_to_binary(User),
        <<"}\n">>
    ]),
    {Record, P9}.

trace(0, Payload, Acc) ->
    {lists:reverse(Acc), Payload};
trace(N, Payload, Acc) ->
    {X, Next} = step(Payload),
    trace(N - 1, Next, [binary:at(<<"0123456789abcdef">>, X rem 16) | Acc]).

%% Advances the xorshift64 state and returns it.
step(#records{state = X0} = Payload) ->
    X1 = X0 bxor ((X0 bsl 13) band ?MASK),
    X2 = X1 bxor (X1 bsr 7),
    X3 = X2 bxor ((X2 bsl 17) band ?MASK),
    {X3, Payload#records{state = X3}}.

between(Low, High, Payload) ->
    {X, Next} = step(Payload),
    {Low + X rem (High - Low + 1), Next}.

pick(Values, Payload) ->
    {X, Next} = step(Payload),
    {element(1 + X rem tuple_size(Values), Values), Next}.

%% The value lists records draw from, as in bench/payload.py.
services() ->
    {<<"checkout">>, <<"cart">>, <<"payments">>, <<"inventory">>, <<"search">>, <<"auth">>,
        <<"gateway">>, <<"notifier">>}.

regions() ->
    {<<"us-east-1">>, <<"us-west-2">>, <<"eu-west-1">>, <<"eu-central-1">>, <<"ap-southeast-1">>}.

methods() ->
    {<<"GET">>, <<"POST">>, <<"PUT">>, <<"DELETE">>}.

routes() ->
    {<<"/api/v1/orders">>, <<"/api/v1/orders/{id}">>, <<"/api/v1/cart">>, <<"/api/v1/users/{id}">>,
        <<"/api/v1/search">>, <<"/healthz">>}.

statuses() ->
    {200, 200, 200, 200, 200, 201, 204, 400, 404, 500}.
